export function getStaticPaths() {
  const paths = [];
  for (const row of getIndex().Packs) {
    const listing = getListing(row);
    const base = packUrl(row).replace(/^\/p\//, '');
    const props = { listing };
    paths.push({ params: { slug: base }, props: { ...props, tab: 'overview' } });
    for (const tab of ['tests', 'connector', 'security']) paths.push({ params: { slug: `${base}/${tab}` }, props: { ...props, tab } });
    for (const test of listing.Tests.filter((t) => !t.Catalog)) {
      paths.push({ params: { slug: `${base}/tests/${test.Id.toLowerCase()}` }, props: { ...props, tab: 'test', testId: test.Id } });
    }
  }
  return paths;
}

